    auto c = torch::zeros(M * N_out, device=A.device);
    const int block_size = 256;
    const int num_blocks = (M * N_out + block_size - 1) / block_size;

    matmul_kernel<<<num_blocks, block_size>>>(a_data_ptr, b_data_ptr, c.data_ptr<float()>, M, K, N_out);

    return c;
}
"""

